'use client';

import { useId } from 'react';

import { WordRoll } from '@/components/core/word-roll';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import {
  pressedQuietOf,
  pressedSolidOf,
  spokenUnless,
} from '@/registry/ndeko/lib/demonstration';
import {
  ArrowUpIcon,
  CheckIcon,
  RotateCcwIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import {
  Popover,
  PopoverContent,
  PopoverTitle,
  PopoverTrigger,
} from '@/registry/ndeko/ui/popover';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/registry/ndeko/ui/tooltip';

import { Collapse } from './_parts/collapse';
import {
  compactionLineOf,
  freeTokensOf,
  LEVEL_LABELS,
  LEVEL_TONE,
  LEVEL_WORD,
  levelOf,
  PART_FILL,
  RESERVE_STYLE,
  shareOf,
  TURNS,
  usedTokensOf,
  type Compaction,
  type ContextBudget,
} from './_parts/context';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { TokenCount } from './_parts/token-count';
import {
  COMPACT_STEPS,
  contextStateAt,
  reduceContext,
  sendStep,
  useContextSession,
  type CompactStatus,
  type ContextSession,
  type ContextStep,
} from './_parts/use-context-demo';

const RING_SIZE = 28;

const RING_STROKE = 3;

const RING_RADIUS = (RING_SIZE - RING_STROKE) / 2;

const RING_CENTER = RING_SIZE / 2;

const CIRCUMFERENCE = 2 * Math.PI * RING_RADIUS;

const WARNING_FROM = 0.85;

const COMPACT_LABELS: Record<MorphState, string> = {
  idle: 'Compact older turns',
  busy: 'Compacting',
  done: 'Compacted',
};

const RING_TRIGGER =
  'focus-visible:ring-ring focus-visible:ring-offset-background inline-flex size-8 cursor-pointer items-center justify-center rounded-full transition-[background-color,scale] duration-200 outline-none focus-visible:ring-2 focus-visible:ring-offset-2';

function percentLabelOf(share: number) {
  const percent = Math.round(share * 100);
  return `${percent}%`;
}

function dashOffsetOf(share: number) {
  const bounded = Math.min(1, Math.max(0, share));
  const remaining = 1 - bounded;
  return CIRCUMFERENCE * remaining;
}

function ringToneOf(isWarning: boolean) {
  if (isWarning) {
    return {
      trigger: 'bg-warning/10 hover:bg-warning/15',
      track: 'stroke-warning/25',
      fill: 'stroke-warning',
    };
  }
  return {
    trigger: 'hover:bg-foreground/5',
    track: 'stroke-foreground/10',
    fill: 'stroke-chart-1',
  };
}

function morphStateOf(status: CompactStatus): MorphState {
  if (status === 'compacting') {
    return 'busy';
  }
  return 'idle';
}

function traceOf(compaction: Compaction | null, isCompactShown: boolean) {
  if (isCompactShown) {
    return null;
  }
  return compaction;
}

function RingGlyph({
  share,
  isWarning,
}: {
  share: number;
  isWarning: boolean;
}) {
  const tone = ringToneOf(isWarning);
  const dashOffset = dashOffsetOf(share);

  return (
    <svg
      aria-hidden='true'
      width={RING_SIZE}
      height={RING_SIZE}
      viewBox={`0 0 ${RING_SIZE} ${RING_SIZE}`}
      className='-rotate-90'
    >
      <circle
        cx={RING_CENTER}
        cy={RING_CENTER}
        r={RING_RADIUS}
        fill='none'
        strokeWidth={RING_STROKE}
        className={cn('transition-[stroke] duration-300', tone.track)}
      />
      <circle
        cx={RING_CENTER}
        cy={RING_CENTER}
        r={RING_RADIUS}
        fill='none'
        strokeWidth={RING_STROKE}
        strokeLinecap='round'
        strokeDasharray={CIRCUMFERENCE}
        strokeDashoffset={dashOffset}
        className={cn(
          'transition-[stroke-dashoffset,stroke] duration-500 ease-(--ease-out-strong)',
          tone.fill
        )}
      />
    </svg>
  );
}

function BreakdownRows({ budget }: { budget: ContextBudget }) {
  const free = freeTokensOf(budget);
  const parts = budget.parts.filter((part) => part.tokens > 0);

  return (
    <ul aria-label='What fills the context' className='flex flex-col'>
      {parts.map((part) => (
        <li key={part.id} className='flex h-7 items-center gap-2.5 text-[13px]'>
          <span
            aria-hidden='true'
            className='size-2 shrink-0 rounded-full'
            style={{ backgroundColor: PART_FILL[part.id] }}
          />
          <span className='min-w-0 flex-1 truncate'>{part.label}</span>
          <TokenCount tokens={part.tokens} className='text-muted-foreground' />
        </li>
      ))}
      <li className='flex h-7 items-center gap-2.5 text-[13px]'>
        <span
          aria-hidden='true'
          className='bg-foreground/[0.08] size-2 shrink-0 rounded-full'
        />
        <span className='min-w-0 flex-1 truncate'>Free</span>
        <TokenCount tokens={free} className='text-muted-foreground' />
      </li>
      <li className='flex h-7 items-center gap-2.5 text-[13px]'>
        <span
          aria-hidden='true'
          className='size-2 shrink-0 rounded-full'
          style={RESERVE_STYLE}
        />
        <span className='min-w-0 flex-1 truncate'>Held for the answer</span>
        <TokenCount tokens={budget.reserve} className='text-muted-foreground' />
      </li>
    </ul>
  );
}

const PLAIN_TITLE = <p className='text-sm leading-none font-medium'>Context</p>;

export type ContextBreakdownProps = {
  budget: ContextBudget;
  canCompact?: boolean;
  compactStatus?: CompactStatus;
  compaction?: Compaction | null;
  onCompact?: () => void;
  /** The heading of the panel. A popover passes its own title element so it is named by it. */
  title?: React.ReactNode;
  /** Shows Compact held down, for a demonstration that presses it. */
  isCompactPressed?: boolean;
  className?: string;
};

/**
 * What fills the context, part by part, with Compact when older turns can be folded. The ring opens
 * it in a popover, and a page can draw it in place.
 */
export function ContextBreakdown({
  budget,
  canCompact = false,
  compactStatus = 'idle',
  compaction = null,
  onCompact,
  title = PLAIN_TITLE,
  isCompactPressed = false,
  className,
}: ContextBreakdownProps) {
  const used = usedTokensOf(budget);
  const level = levelOf(budget);
  const isCompacting = compactStatus === 'compacting';
  const isCompactShown = canCompact || isCompacting;
  const trace = traceOf(compaction, isCompactShown);

  return (
    <div className={cn('flex flex-col gap-3', className)}>
      <div className='flex items-start justify-between gap-3'>
        <div className='min-w-0'>
          {title}
          <p
            className={cn(
              'mt-1 text-xs transition-colors duration-200',
              LEVEL_TONE[level]
            )}
          >
            <WordRoll text={LEVEL_WORD[level]} labels={LEVEL_LABELS} />
          </p>
        </div>
        <p className='text-[13px] tabular-nums'>
          <TokenCount tokens={used} className='font-medium' />
          <span className='text-muted-foreground'>
            {' of '}
            <TokenCount tokens={budget.limit} />
          </span>
        </p>
      </div>
      <BreakdownRows budget={budget} />
      {isCompactShown && (
        <MorphButton
          type='button'
          size='sm'
          variant='outline'
          state={morphStateOf(compactStatus)}
          labels={COMPACT_LABELS}
          onClick={onCompact}
          className={cn('self-start', pressedQuietOf(isCompactPressed))}
        />
      )}
      {trace && (
        <p className='text-muted-foreground flex items-center gap-2 text-xs'>
          <CheckIcon className='text-success-foreground size-3.5' />
          {compactionLineOf(trace)}
        </p>
      )}
    </div>
  );
}

/** `inline` makes the ring a toggle and leaves the breakdown to the page, which draws `ContextBreakdown` where it wants it. */
export type ContextRingSurface = 'popover' | 'inline';

export type ContextRingProps = {
  budget: ContextBudget;
  canCompact?: boolean;
  compactStatus?: CompactStatus;
  compaction?: Compaction | null;
  onCompact?: () => void;
  as?: ContextRingSurface;
  /** With `inline`: whether the page shows the breakdown. */
  isOpen?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
  /** With `inline`: the id of the element the page draws the breakdown in. */
  breakdownId?: string;
  /** Shows the ring held down, for a demonstration that presses it. */
  isPressed?: boolean;
  className?: string;
};

export function ContextRing({
  budget,
  canCompact = false,
  compactStatus = 'idle',
  compaction = null,
  onCompact,
  as = 'popover',
  isOpen = false,
  onOpenChange,
  breakdownId,
  isPressed = false,
  className,
}: ContextRingProps) {
  const used = usedTokensOf(budget);
  const share = shareOf(used, budget);
  const isWarning = share > WARNING_FROM;
  const percentLabel = percentLabelOf(share);
  const tone = ringToneOf(isWarning);
  const triggerLabel = `Context ${percentLabel} used, open the breakdown`;

  function toggle() {
    onOpenChange?.(!isOpen);
  }

  if (as === 'inline') {
    return (
      <Tooltip>
        <TooltipTrigger
          render={
            <button
              type='button'
              aria-label={triggerLabel}
              aria-expanded={isOpen}
              aria-controls={breakdownId}
              onClick={toggle}
              className={cn(
                RING_TRIGGER,
                'active:scale-[0.97]',
                tone.trigger,
                pressedQuietOf(isPressed),
                className
              )}
            />
          }
        >
          <RingGlyph share={share} isWarning={isWarning} />
        </TooltipTrigger>
        <TooltipContent>{percentLabel} of the context used</TooltipContent>
      </Tooltip>
    );
  }

  return (
    <Popover>
      <Tooltip>
        <TooltipTrigger
          render={
            <PopoverTrigger
              render={
                <button
                  type='button'
                  aria-label={triggerLabel}
                  className={cn(RING_TRIGGER, tone.trigger, className)}
                />
              }
            />
          }
        >
          <RingGlyph share={share} isWarning={isWarning} />
        </TooltipTrigger>
        <TooltipContent>{percentLabel} of the context used</TooltipContent>
      </Tooltip>
      <PopoverContent side='top' align='end' className='w-72 p-3'>
        <ContextBreakdown
          budget={budget}
          canCompact={canCompact}
          compactStatus={compactStatus}
          compaction={compaction}
          onCompact={onCompact}
          title={<PopoverTitle>Context</PopoverTitle>}
        />
      </PopoverContent>
    </Popover>
  );
}

const MESSAGES = [
  'Start the quarterly review for Brightmoor Supply',
  'Use the Q3 invoices I attached',
  'Check their pricing page as well',
  'Which lines are above the list price?',
  'Add the contract terms on bulk orders',
  'How much did we overpay in total?',
  'Split that by month',
  'Draft an email asking for a credit',
  'Make it shorter and less formal',
  'Attach the comparison as a CSV',
  'Add a line about the October order',
  'Send it to accounts once I approve',
];

/** The demo opens on a conversation already half way to the limit. */
const OPENING_TURNS = 6;

const SEND_EVERY_MS = 1100;

function sendSteps(): ContextStep[] {
  const steps: ContextStep[] = [];
  for (let count = OPENING_TURNS + 1; count <= TURNS.length; count += 1) {
    steps.push(sendStep(SEND_EVERY_MS, count));
  }
  return steps;
}

function ringStep(after: number, isOpen: boolean): ContextStep {
  return {
    after,
    by: 'demo',
    press: 'ring',
    action: { type: 'breakdown', isOpen },
  };
}

/** Messages go out until the ring warns, the breakdown opens, the older turns are folded and it closes. */
const SCRIPT: ContextStep[] = [
  ...sendSteps(),
  ringStep(900, true),
  ...COMPACT_STEPS,
  ringStep(2400, false),
];

const RESTING = { ...contextStateAt(TURNS.length), isBreakdownOpen: true };

const SESSION: ContextSession = {
  reducer: reduceContext,
  initial: contextStateAt(OPENING_TURNS),
  resting: RESTING,
  script: SCRIPT,
  loopAfter: 2600,
};

function nextMessageOf(sentCount: number) {
  return MESSAGES[sentCount] ?? null;
}

function ringAnnouncementOf(budget: ContextBudget, sentCount: number) {
  if (sentCount === OPENING_TURNS) {
    return '';
  }
  const used = usedTokensOf(budget);
  const share = shareOf(used, budget);
  const percent = percentLabelOf(share);
  const level = levelOf(budget);
  return `Message sent. Context ${percent} used, ${LEVEL_WORD[level]}`;
}

export default function Run07() {
  const {
    ref,
    isInView,
    isAutoplaying,
    pressed,
    turns,
    budget,
    compaction,
    compactStatus,
    canCompact,
    isBreakdownOpen,
    compact,
    send,
    setBreakdownOpen,
    replay,
  } = useContextSession(SESSION);
  const breakdownId = useId();
  const sentCount = turns.length;
  const nextMessage = nextMessageOf(sentCount);
  const hasNext = nextMessage !== null;
  const announcement = ringAnnouncementOf(budget, sentCount);

  useKeptHeight(ref);

  return (
    <div
      ref={ref}
      className='flex min-h-[27.5rem] w-full max-w-[26rem] flex-col gap-2'
    >
      <ClockGate isActive={isInView}>
        <div className='bg-card hairline-ring ring-border flex flex-col rounded-xl p-2.5 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
          <p className='min-h-10 px-1.5 pt-1 text-[13px] leading-5'>
            <Swap swapKey={nextMessage ?? 'done'}>
              {hasNext && nextMessage}
              {!hasNext && (
                <span className='text-muted-foreground'>
                  That was the last demo message
                </span>
              )}
            </Swap>
          </p>
          <div className='mt-2 flex items-center gap-2'>
            <Badge variant='secondary'>Claude Haiku</Badge>
            <span className='flex-1' />
            <ContextRing
              as='inline'
              budget={budget}
              isOpen={isBreakdownOpen}
              onOpenChange={setBreakdownOpen}
              breakdownId={breakdownId}
              isPressed={pressed === 'ring'}
            />
            <Button
              type='button'
              size='icon'
              aria-label='Send this demo message'
              disabled={!hasNext}
              onClick={send}
              className={pressedSolidOf(pressed === 'send')}
            >
              <ArrowUpIcon />
            </Button>
          </div>
          <Collapse open={isBreakdownOpen} id={breakdownId}>
            <ContextBreakdown
              budget={budget}
              canCompact={canCompact}
              compactStatus={compactStatus}
              compaction={compaction}
              onCompact={compact}
              isCompactPressed={pressed === 'compact'}
              className='bg-foreground/[0.03] mt-2.5 rounded-lg p-3'
            />
          </Collapse>
        </div>
      </ClockGate>
      <div className='flex h-7 items-center justify-between gap-2'>
        <p className='text-muted-foreground px-1 text-xs'>
          Each message adds its turn to the context
        </p>
        <Button
          type='button'
          variant='ghost'
          size='sm'
          onClick={replay}
          className='text-muted-foreground'
        >
          <RotateCcwIcon />
          Start over
        </Button>
      </div>
      <LiveRegion message={spokenUnless(isAutoplaying, announcement)} />
    </div>
  );
}

'use client';

import { motion, type Transition } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { EASE_OUT_STRONG, INSTANT } from '@/registry/ndeko/lib/motion-presets';

const OPEN = { height: 'auto', opacity: 1 };

const CLOSED = { height: 0, opacity: 0 };

const OPENING: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

const CLOSING: Transition = { duration: 0.14, ease: EASE_OUT_STRONG };

function targetOf(open: boolean) {
  if (open) {
    return OPEN;
  }
  return CLOSED;
}

function transitionOf(open: boolean, shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  if (open) {
    return OPENING;
  }
  return CLOSING;
}

type CollapseProps = {
  open: boolean;
  id?: string;
  children: React.ReactNode;
};

/**
 * A panel that folds and keeps its content in the page. Open, it takes the height of its content
 * without animating it, so a row that arrives inside moves once, by its own presence. The padding
 * leaves room for focus rings and the margin takes it back, also when the panel is closed.
 */
export function Collapse({ open, id, children }: CollapseProps) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <motion.div
      id={id}
      inert={!open}
      initial={false}
      animate={targetOf(open)}
      transition={transitionOf(open, shouldReduceMotion)}
      className='-m-1 overflow-hidden p-1'
    >
      {children}
    </motion.div>
  );
}

import { hatchOf } from '@/registry/ndeko/lib/hatch';

export type ContextPartId =
  'system' | 'tools' | 'files' | 'summary' | 'conversation';

/** A place in the window: one of its parts, the room left, or what is held back for the answer. */
export type ContextSlot = ContextPartId | 'free' | 'reserve';

export type ContextItem = {
  id: string;
  label: string;
  tokens: number;
};

export type ContextPart = {
  id: ContextPartId;
  label: string;
  tokens: number;
  items: ContextItem[];
};

export type ContextBudget = {
  limit: number;
  /** Held back for the model's answer: never filled by the context. */
  reserve: number;
  parts: ContextPart[];
};

export type ContextLevel = 'room' | 'filling' | 'compact';

export type Compaction = {
  foldedTurns: number;
  summaryTokens: number;
};

export const CONTEXT_LIMIT = 200_000;

export const CONTEXT_RESERVE = 16_000;

/** Parts are parts of one whole, not entities: they take the chart ramp and a muted fill, never the series. */
export const PART_FILL: Record<ContextPartId, string> = {
  system: 'color-mix(in oklab, var(--muted-foreground) 30%, transparent)',
  tools: 'var(--chart-3)',
  files: 'var(--chart-2)',
  summary: 'var(--chart-4)',
  conversation: 'var(--chart-1)',
};

export const RESERVE_STYLE = {
  backgroundColor:
    'color-mix(in oklab, var(--muted-foreground) 8%, transparent)',
  backgroundImage: hatchOf('var(--muted-foreground)', 40),
};

export const LEVEL_WORD: Record<ContextLevel, string> = {
  room: 'Plenty of room',
  filling: 'Filling up',
  compact: 'Compact soon',
};

export const LEVEL_LABELS = [
  LEVEL_WORD.room,
  LEVEL_WORD.filling,
  LEVEL_WORD.compact,
];

export const LEVEL_TONE: Record<ContextLevel, string> = {
  room: 'text-muted-foreground',
  filling: 'text-foreground',
  compact: 'text-warning-foreground',
};

const FILLING_FROM = 0.6;

const COMPACT_FROM = 0.85;

/** The newest turns stay word for word after a compaction. */
const KEPT_TURNS = 2;

const SUMMARY_SHARE = 0.08;

export const SYSTEM_ITEMS: ContextItem[] = [
  { id: 'system-prompt', label: 'System prompt', tokens: 4_100 },
  { id: 'system-notes', label: 'Saved notes', tokens: 2_100 },
];

export const TOOL_ITEMS: ContextItem[] = [
  { id: 'tool-search', label: 'web_search results', tokens: 1_900 },
  { id: 'tool-page', label: 'fetch_page result', tokens: 2_300 },
  { id: 'tool-sheet', label: 'read_sheet rows', tokens: 2_600 },
  { id: 'tool-script', label: 'run_script output', tokens: 1_800 },
];

export const FILE_ITEMS: ContextItem[] = [
  { id: 'file-invoices', label: 'q3-invoices.xlsx', tokens: 21_400 },
  { id: 'file-contract', label: 'brightmoor-contract.pdf', tokens: 18_600 },
  { id: 'file-pricing', label: 'pricing-page.html', tokens: 9_800 },
  { id: 'file-notes', label: 'vendor-notes.md', tokens: 3_100 },
];

const TURN_TOKENS = [
  5_200, 7_400, 9_800, 6_100, 12_400, 8_300, 10_900, 7_700, 13_600, 9_200,
  11_800, 8_600,
];

function turnOf(tokens: number, index: number): ContextItem {
  const number = index + 1;
  return { id: `turn-${number}`, label: `Turn ${number}`, tokens };
}

export const TURNS: ContextItem[] = TURN_TOKENS.map(turnOf);

export function sumTokens(items: readonly { tokens: number }[]) {
  let total = 0;
  for (const item of items) {
    total += item.tokens;
  }
  return total;
}

/** What the run holds before any conversation: system, tools and every file. */
const SYSTEM_TOKENS = sumTokens(SYSTEM_ITEMS);

const TOOL_TOKENS = sumTokens(TOOL_ITEMS);

const FILE_TOKENS = sumTokens(FILE_ITEMS);

export const BASE_TOKENS = SYSTEM_TOKENS + TOOL_TOKENS + FILE_TOKENS;

export function usedTokensOf(budget: ContextBudget) {
  return sumTokens(budget.parts);
}

export function freeTokensOf(budget: ContextBudget) {
  const used = usedTokensOf(budget);
  const free = budget.limit - budget.reserve - used;
  return Math.max(0, free);
}

export function shareOf(tokens: number, budget: ContextBudget) {
  return tokens / budget.limit;
}

export function percentOf(tokens: number, budget: ContextBudget) {
  const share = shareOf(tokens, budget);
  return share * 100;
}

export function levelOf(budget: ContextBudget): ContextLevel {
  const used = usedTokensOf(budget);
  const share = shareOf(used, budget);
  if (share < FILLING_FROM) {
    return 'room';
  }
  if (share <= COMPACT_FROM) {
    return 'filling';
  }
  return 'compact';
}

export function turnsWithin(conversationTokens: number) {
  const turns: ContextItem[] = [];
  let total = 0;
  for (const turn of TURNS) {
    const next = total + turn.tokens;
    if (next > conversationTokens) {
      break;
    }
    turns.push(turn);
    total = next;
  }
  return turns;
}

/** The tokens of the turns a compaction folds away: every turn of the conversation but the newest ones. */
export function foldableTokensOf(budget: ContextBudget) {
  const conversation = budget.parts.find((part) => part.id === 'conversation');
  if (!conversation) {
    return 0;
  }
  const foldedCount = conversation.items.length - KEPT_TURNS;
  if (foldedCount < 1) {
    return 0;
  }
  const folded = conversation.items.slice(0, foldedCount);
  return sumTokens(folded);
}

export function compactionOf(turns: ContextItem[]): Compaction | null {
  const foldedTurns = turns.length - KEPT_TURNS;
  if (foldedTurns < 2) {
    return null;
  }
  const folded = turns.slice(0, foldedTurns);
  const foldedTokens = sumTokens(folded);
  const rawSummary = foldedTokens * SUMMARY_SHARE;
  const summaryHundreds = Math.round(rawSummary / 100);
  const summaryTokens = summaryHundreds * 100;
  return { foldedTurns, summaryTokens };
}

function partOf(
  id: ContextPartId,
  label: string,
  items: ContextItem[]
): ContextPart {
  return { id, label, tokens: sumTokens(items), items };
}

function turnCountOf(count: number) {
  if (count === 1) {
    return '1 turn';
  }
  return `${count} turns`;
}

type BudgetInput = {
  turns: ContextItem[];
  removedFileIds: readonly string[];
  compaction: Compaction | null;
};

export function budgetOf({
  turns,
  removedFileIds,
  compaction,
}: BudgetInput): ContextBudget {
  const files = FILE_ITEMS.filter((file) => !removedFileIds.includes(file.id));
  const foldedCount = compaction?.foldedTurns ?? 0;
  const liveTurns = turns.slice(foldedCount);
  const parts: ContextPart[] = [
    partOf('system', 'System', SYSTEM_ITEMS),
    partOf('tools', 'Tools', TOOL_ITEMS),
    partOf('files', 'Files', files),
  ];
  if (compaction) {
    const summaryLabel = `Summary of ${turnCountOf(compaction.foldedTurns)}`;
    const summary = {
      id: 'summary',
      label: summaryLabel,
      tokens: compaction.summaryTokens,
    };
    parts.push(partOf('summary', 'Summary', [summary]));
  }
  parts.push(partOf('conversation', 'Conversation', liveTurns));
  return { limit: CONTEXT_LIMIT, reserve: CONTEXT_RESERVE, parts };
}

export function compactionLineOf(compaction: Compaction) {
  const turns = turnCountOf(compaction.foldedTurns);
  const thousands = compaction.summaryTokens / 1000;
  const summary = `${thousands.toFixed(1)}k`;
  return `Folded ${turns} into a ${summary} summary`;
}

'use client';

import { MotionNumber } from '@/components/core/motion-number';

const THOUSANDS: Intl.NumberFormatOptions = { maximumFractionDigits: 1 };

type TokenCountProps = {
  tokens: number;
  className?: string;
};

export function TokenCount({ tokens, className }: TokenCountProps) {
  const thousands = tokens / 1000;
  return (
    <MotionNumber
      value={thousands}
      format={THOUSANDS}
      suffix='k'
      className={className}
    />
  );
}

'use client';

import {
  useSession,
  type SessionConfig,
  type SessionStep,
} from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';

import {
  budgetOf,
  compactionOf,
  TURNS,
  type Compaction,
  type ContextSlot,
} from './context';

export type CompactStatus = 'idle' | 'compacting';

const COMPACT_MS = 900;

/** An offer that waits on a person is taken by the demonstration after this long. */
const COMPACT_AFTER_MS = 2500;

export type ContextState = {
  /** How many turns of the conversation the context holds. */
  turnCount: number;
  removedFileIds: string[];
  compaction: Compaction | null;
  compactStatus: CompactStatus;
  /** The part a demonstration points at, in the views that light one part. */
  spotlight: ContextSlot | null;
  /** Whether the breakdown is open, in the views that fold it. */
  isBreakdownOpen: boolean;
};

export type ContextAction =
  | { type: 'turn' }
  | { type: 'removeFile'; fileId: string }
  | { type: 'compact' }
  | { type: 'compacted' }
  | { type: 'spotlight'; slot: ContextSlot | null }
  | { type: 'breakdown'; isOpen: boolean };

export type ContextStep = SessionStep<ContextState, ContextAction>;

export type ContextSession = SessionConfig<ContextState, ContextAction>;

export function contextStateAt(turnCount: number): ContextState {
  return {
    turnCount,
    removedFileIds: [],
    compaction: null,
    compactStatus: 'idle',
    spotlight: null,
    isBreakdownOpen: false,
  };
}

function turnsIn(state: ContextState) {
  return TURNS.slice(0, state.turnCount);
}

/** Compact is offered again only once new turns can be folded into the summary. */
function canCompactIn(state: ContextState) {
  const turns = turnsIn(state);
  const next = compactionOf(turns);
  const foldedNow = state.compaction?.foldedTurns ?? 0;
  const foldableNext = next?.foldedTurns ?? 0;
  const hasNewTurnsToFold = foldableNext > foldedNow;
  const isIdle = state.compactStatus === 'idle';
  return hasNewTurnsToFold && isIdle;
}

function withTurn(state: ContextState): ContextState {
  const hasMore = state.turnCount < TURNS.length;
  if (!hasMore) {
    return state;
  }
  return { ...state, turnCount: state.turnCount + 1 };
}

function withFileRemoved(state: ContextState, fileId: string): ContextState {
  const removedFileIds = [...state.removedFileIds, fileId];
  return { ...state, removedFileIds };
}

function withCompactStarted(state: ContextState): ContextState {
  if (!canCompactIn(state)) {
    return state;
  }
  return { ...state, compactStatus: 'compacting' };
}

/** The script and the hand of a person may both land the same compaction: only the first one counts. */
function withCompactLanded(state: ContextState): ContextState {
  if (state.compactStatus !== 'compacting') {
    return state;
  }
  const turns = turnsIn(state);
  const compaction = compactionOf(turns);
  return { ...state, compaction, compactStatus: 'idle' };
}

export function reduceContext(
  state: ContextState,
  action: ContextAction
): ContextState {
  switch (action.type) {
    case 'turn':
      return withTurn(state);
    case 'removeFile':
      return withFileRemoved(state, action.fileId);
    case 'compact':
      return withCompactStarted(state);
    case 'compacted':
      return withCompactLanded(state);
    case 'spotlight':
      return { ...state, spotlight: action.slot };
    case 'breakdown':
      return { ...state, isBreakdownOpen: action.isOpen };
  }
}

function hasCompacted(state: ContextState) {
  const isCompacting = state.compactStatus === 'compacting';
  const isCompacted = state.compaction !== null;
  return isCompacting || isCompacted;
}

/** A turn that arrives on its own: the conversation going on, which always plays. */
export function turnStep(after: number): ContextStep {
  return { after, action: { type: 'turn' } };
}

/** A message a person sends: the demonstration presses Send for them until they take over. */
export function sendStep(after: number, turnCount: number): ContextStep {
  return {
    after,
    by: 'person',
    press: 'send',
    action: { type: 'turn' },
    isAnswered: (state) => state.turnCount >= turnCount,
  };
}

/** Compact pressed by the demonstration once it is offered, then the summary landing. */
export const COMPACT_STEPS: ContextStep[] = [
  {
    after: COMPACT_AFTER_MS,
    by: 'person',
    press: 'compact',
    action: { type: 'compact' },
    isAnswered: hasCompacted,
  },
  { after: COMPACT_MS, action: { type: 'compacted' } },
];

/** The demos open on a conversation already under way and fill it one turn at a time. */
const OPENING_TURNS = 5;

const TURN_EVERY_MS = 900;

function arrivingTurns(): ContextStep[] {
  const count = TURNS.length - OPENING_TURNS;
  return Array.from({ length: count }, () => turnStep(TURN_EVERY_MS));
}

/** The conversation fills until Compact is offered, the demonstration takes it and the summary lands. */
export const FILLING_SCRIPT: ContextStep[] = [
  ...arrivingTurns(),
  ...COMPACT_STEPS,
];

/**
 * Under reduced motion nothing plays: the context rests full, with Compact on offer, which a person
 * can still take.
 */
export const FILLING_SESSION: ContextSession = {
  reducer: reduceContext,
  initial: contextStateAt(OPENING_TURNS),
  resting: contextStateAt(TURNS.length),
  script: FILLING_SCRIPT,
  loopAfter: 3400,
};

/** A context that fills turn by turn, played as a session: turns arrive, a person removes files and compacts. */
export function useContextSession(session: ContextSession) {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(session);
  const { schedule, clearAll } = useTimeouts();
  const turns = turnsIn(state);
  const { removedFileIds, compaction } = state;
  const budget = budgetOf({ turns, removedFileIds, compaction });
  const budgetBefore = budgetOf({ turns, removedFileIds, compaction: null });
  const canCompact = canCompactIn(state);
  const canReplay = isFinished && !isAutoplaying;

  function removeFile(fileId: string) {
    act({ type: 'removeFile', fileId });
  }

  function compact() {
    if (!canCompact) {
      return;
    }
    act({ type: 'compact' });
    schedule(() => act({ type: 'compacted' }), COMPACT_MS);
  }

  function send() {
    act({ type: 'turn' });
  }

  function setBreakdownOpen(isOpen: boolean) {
    act({ type: 'breakdown', isOpen });
  }

  function replay() {
    clearAll();
    restart();
  }

  return {
    ref,
    isInView,
    isAutoplaying,
    canReplay,
    pressed,
    turns,
    budget,
    budgetBefore,
    compaction,
    compactStatus: state.compactStatus,
    canCompact,
    spotlight: state.spotlight,
    isBreakdownOpen: state.isBreakdownOpen,
    removeFile,
    compact,
    send,
    setBreakdownOpen,
    replay,
  };
}
